CONTRACOES = {'do': ('de', 'o'), 'na': ('em', 'a'), 'pelo': ('por', 'o'), 'à': ('a', 'a')}

def investigar_preposicao(palavra, frase):
    if palavra.lower() in CONTRACOES:
        prep, art = CONTRACOES[palavra.lower()]
        return f'contração: preposição {prep} + artigo {art}'
    if liga_oracoes(palavra, frase):
        return 'investigar conjunção'
    regente, regido = termos_ligados(palavra, frase)
    return f'preposição ligando {regente} a {regido}'

RELACOES = {
    'mas': 'oposição', 'porém': 'oposição', 'e': 'adição',
    'porque': 'causa (ou explicação)', 'embora': 'concessão', 'se': 'condição (ou integrante)'
}

def investigar_conjuncao(palavra, frase):
    if retoma_termo_anterior(palavra, frase):
        return 'pronome relativo'
    if not liga_oracoes_ou_termos_equivalentes(palavra, frase):
        return 'investigar preposição ou advérbio'
    relacao = RELACOES.get(palavra.lower(), 'analisar o sentido')
    return f'conjunção com relação de {relacao} (confirmar no contexto)'
